package p8mutation

import "time"

// optimisticConcurrencyRuntimeMutations is deliberately isolated from the
// release-wide Catalog until the runtime slice has passed its focused mutant
// run. Each entry changes one authority or one retry/cleanup invariant.
func optimisticConcurrencyRuntimeMutations() []Mutation {
	runtimeGate := Gate{Directory: "go", Package: "./runtime", Test: "TestOptimisticConcurrencyCreateUpdateDeleteAndLegacyBypassSQLite"}
	sqlGate := Gate{Directory: "go", Package: "./internal/mutation/sql", Test: "TestVersionedOptimisticConcurrencySQLIsExactCAS"}
	bindGate := Gate{Directory: "go", Package: "./internal/mutation/bind", Test: "TestOptimisticConcurrencyFieldHasOneClosedRuntimeOwner"}
	nestedGate := Gate{Directory: "go", Package: "./runtime", Test: "TestOptimisticConcurrencyNestedEveryWrittenRowRequiresExpectation"}
	hookOwnedCreateGate := Gate{Directory: "go", Package: "./runtime", Test: "TestP8CallerCreatePreHookDefersOnlyGeneratedHookOwnedFields"}
	mutation := func(label, summary string, patch Patch, gate Gate) Mutation {
		return Mutation{Label: label, Summary: summary, Patches: []Patch{patch}, Gate: gate, Timeout: 3 * time.Minute}
	}
	return []Mutation{
		mutation("CONCURRENCY_RUNTIME_CREATE_INITIALIZES_TWO", "initialize a new versioned row with two instead of one", Patch{Path: "go/internal/mutation/bind/input.go", Before: "one, err := policyir.SignedValue(policyir.ValueInt64, 1)", After: "one, err := policyir.SignedValue(policyir.ValueInt64, 2)"}, bindGate),
		mutation("CONCURRENCY_RUNTIME_OMITS_INCREMENT", "leave the stored version unchanged after a successful update", Patch{Path: "go/internal/mutation/sql/render.go", Before: "assignments = append(assignments, column+\" = (\"+column+\" + 1)\")", After: "assignments = append(assignments, column+\" = \"+column)"}, sqlGate),
		mutation("CONCURRENCY_RUNTIME_OMITS_EQUALITY_CAS", "drop the observed-version predicate from the atomic update", Patch{Path: "go/internal/mutation/sql/render.go", Before: "\t\tupdateBindings = append(updateBindings, Binding{kind: PriorResultBinding, statementIndex: 0, field: *context.concurrency})\n\t\tupdateWhere += \" AND \" + context.qualified(field.Column) + \" = \" + context.dialect.Placeholder(len(updateBindings))\n\t\tupdateWhere += \" AND \" + context.qualified(field.Column) + \" < 9223372036854775807\"", After: "\t\tupdateWhere += \" AND \" + context.qualified(field.Column) + \" < 9223372036854775807\""}, sqlGate),
		mutation("CONCURRENCY_RUNTIME_OMITS_OVERFLOW_GUARD", "allow a versioned update to overflow int64", Patch{Path: "go/internal/mutation/sql/render.go", Before: "\t\tupdateWhere += \" AND \" + context.qualified(field.Column) + \" < 9223372036854775807\"", After: "\t\t_ = field // mutant: overflow guard omitted"}, sqlGate),
		mutation("CONCURRENCY_RUNTIME_ORDINARY_RENDER_GAINS_AUTHORITY", "let the ordinary renderer consume an existing-row versioned mutation", Patch{Path: "go/internal/mutation/sql/render.go", Before: "\t\t\tif !versioned {\n\t\t\t\treturn Program{}, fail(CodeUnsupported, node.ModelID(), value, \"optimistic-concurrency mutation requires an explicit expectation\", nil)\n\t\t\t}", After: "\t\t\tif false && !versioned {\n\t\t\t\treturn Program{}, fail(CodeUnsupported, node.ModelID(), value, \"optimistic-concurrency mutation requires an explicit expectation\", nil)\n\t\t\t}"}, sqlGate),
		mutation("CONCURRENCY_RUNTIME_PROGRAM_OMITS_PRECHECK_CAPABILITY", "render a versioned program without its required precheck capability", Patch{Path: "go/internal/mutation/sql/render.go", Before: "program.requiresConcurrencyPrecheck = versioned && (node.Operation() == mutationir.Update || node.Operation() == mutationir.Delete)", After: "program.requiresConcurrencyPrecheck = false"}, sqlGate),
		mutation("CONCURRENCY_RUNTIME_SKIPS_CLAIM_EQUALITY", "accept the locked row without comparing the closed expectation", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\tif err := claim.validateObserved(preimage, field, initial.Operation()); err != nil {\n\t\treturn golem.Row[M]{}, publicScalarMutationError(descriptor.Metadata().ModelID(), err)\n\t}", After: "\t_ = claim // mutant: locked preimage accepted without expectation equality"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_ACCEPTS_MAX_TOKEN", "allow MaxInt64 rows to reach hooks and mutation SQL", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\tif observed == math.MaxInt64 {\n\t\treturn 0, scalarMutationError(operation, scalarMutationConflict, mutationsql.SelectPreImage, 0, \"mutation concurrency token is exhausted\", nil)\n\t}", After: "\tif false && observed == math.MaxInt64 {\n\t\treturn 0, scalarMutationError(operation, scalarMutationConflict, mutationsql.SelectPreImage, 0, \"mutation concurrency token is exhausted\", nil)\n\t}"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_LEGACY_ROOT_BYPASS", "allow a generic existing-row write on a versioned root", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\tif _, enabled := fact.OptimisticConcurrency(); !enabled {\n\t\treturn nil\n\t}\n\treturn golem.RuntimeOperationError(golem.CodeBadUserInput, operation, model, golem.FieldID{}, \"mutation request is invalid\", fmt.Errorf(\"optimistic-concurrency mutation requires an explicit expectation\"))", After: "\tif _, enabled := fact.OptimisticConcurrency(); enabled {\n\t\treturn nil // mutant: generic mutation gains versioned authority\n\t}\n\treturn nil"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_NESTED_OWNER_BYPASS", "allow an existing versioned nested/FK-owner row to be written without an expectation", Patch{Path: "go/runtime/mutation_nested.go", Before: "\t\tif _, enabled := model.OptimisticConcurrency(); enabled {", After: "\t\tif _, enabled := model.OptimisticConcurrency(); enabled && false {"}, nestedGate),
		mutation("CONCURRENCY_RUNTIME_OMITS_HOOK_OWNED_CREATE_PREFLIGHT", "bind caller creates strictly before generated BeforeCreate can supply exact ContractIR hook-owned fields", Patch{Path: "go/runtime/mutation_nested.go", Before: "\tmissing := missingRuntimeOwnedFields(input, model.GraphQLHookOwnedCreateFields())", After: "\tmissing := model.GraphQLHookOwnedCreateFields()[:0] // mutant: hook-owned preflight deferral omitted"}, hookOwnedCreateGate),
		mutation("CONCURRENCY_RUNTIME_RETRY_REUSES_ORDINAL_ONE", "report every engine-owned retry as attempt one", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\t\trow, err := execute(ctx, attempt)", After: "\t\trow, err := execute(ctx, 1)"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_REPLAYS_SCOPED_BINDING", "replay a scoped nil-transaction SQLite binding", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\tif source.scoped {\n\t\tmaxAttempts = 1\n\t}", After: "\tif source.transaction != nil {\n\t\tmaxAttempts = 1\n\t}"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_RETRIES_UNIQUE", "treat deterministic uniqueness as replayable provider interference", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\t\tif mutationupsert.UniqueCollision(err) {\n\t\t\treturn golem.Row[M]{}, golem.RuntimeOperationError(golem.CodeConflict, \"upsert\", model, golem.FieldID{}, \"mutation conflicted\", err)\n\t\t}", After: "\t\tif false && mutationupsert.UniqueCollision(err) {\n\t\t\treturn golem.Row[M]{}, golem.RuntimeOperationError(golem.CodeConflict, \"upsert\", model, golem.FieldID{}, \"mutation conflicted\", err)\n\t\t}"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_SUPPRESSES_ABORT_FAILURE", "return the clean refusal even when attempt rollback fails", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\t\t\tif abortErr := attempt.Abort(); abortErr != nil {\n\t\t\t\trow = golem.Row[M]{}\n\t\t\t\tresultErr = golem.RuntimeOperationError(golem.CodeBadUserInput, \"upsert\", descriptor.Metadata().ModelID(), golem.FieldID{}, \"mutation could not be completed\", errors.Join(resultErr, &concurrencyAbortFailure{cause: abortErr}))\n\t\t\t}", After: "\t\t\t_ = attempt.Abort() // mutant: abort failure discarded"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_RECLASSIFIES_DIRTY_SAVEPOINT", "treat a failed create-savepoint rollback as a clean unique collision", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\t\tif rollbackErr != nil || releaseErr != nil || scopeErr != nil {\n\t\t\treturn nil, &absentCreateRollbackFailure{cause: errors.Join(executionErr, rollbackErr, releaseErr, scopeErr)}\n\t\t}", After: "\t\tif rollbackErr != nil || releaseErr != nil || scopeErr != nil {\n\t\t\treturn nil, executionErr // mutant: dirty cleanup masquerades as clean collision\n\t\t}"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_MULTIPLE_ROOT_OBSERVATIONS", "open one root observation per retry attempt", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\tfor attempt := uint32(1); attempt <= maxAttempts; attempt++ {\n\t\trow, err := execute(ctx, attempt)", After: "\tfor attempt := uint32(1); attempt <= maxAttempts; attempt++ {\n\t\tattemptContext, attemptObservation, attemptDeferred := beginDeferredExecutionObservation(ctx, app, source, model, observe.KindMutation, observe.OperationMutationUpsert)\n\t\tdefer func() { finishDeferredObservation(attemptObservation, attemptDeferred, resultErr) }()\n\t\trow, err := execute(attemptContext, attempt)"}, runtimeGate),
		{
			Label:   "CONCURRENCY_RUNTIME_REPREPARES_ABSENT_RETRY_VALUES",
			Summary: "recreate application-owned runtime values inside each absent-upsert attempt",
			Patches: []Patch{{Path: "go/runtime/mutation_concurrency.go", Before: "\treturn executeObservedVersionedUpsertRetries(ctx, caller.app, caller.executor, descriptor.Metadata().ModelID(), func(attemptContext context.Context, attempt uint32) (golem.Row[M], error) {\n\t\treturn executeAbsentVersionedUpsertAttempt(attemptContext, caller.app, caller.executor, descriptor, projection, prepared, caller.policies, hooks, attempt)\n\t})", After: "\treturn executeObservedVersionedUpsertRetries(ctx, caller.app, caller.executor, descriptor.Metadata().ModelID(), func(attemptContext context.Context, attempt uint32) (golem.Row[M], error) {\n\t\tvar prepareErr error\n\t\tprepared, prepareErr = prepareCallerRootUpsert(caller, rootUpsertPrepareRequest{model: model, target: target, create: create, update: update, result: requirements, runtimeValues: newMutationRuntimeValues(), concurrencyAbsent: true})\n\t\tif prepareErr != nil { return golem.Row[M]{}, prepareErr }\n\t\treturn executeAbsentVersionedUpsertAttempt(attemptContext, caller.app, caller.executor, descriptor, projection, prepared, caller.policies, hooks, attempt)\n\t})"}},
			Gate:    runtimeGate, Timeout: 3 * time.Minute,
		},
		{
			Label:   "CONCURRENCY_RUNTIME_PRIVATE_PROBE_PRECEDES_AUTHORIZED_PROBE",
			Summary: "consult private exact existence before caller-authorized reachability",
			Patches: []Patch{{Path: "go/runtime/mutation_concurrency.go", Before: "rows, err = attempt.Query(ctx, prepared.kernel.ProbeStatement())", After: "rows, err = attempt.Query(ctx, prepared.kernel.ExactSelectorProbeStatement())"}},
			Gate:    runtimeGate, Timeout: 3 * time.Minute,
		},
		mutation("CONCURRENCY_RUNTIME_BEFORE_HOOK_PRECEDES_EXPECTATION_CHECK", "invoke Before before comparing the locked token to the expectation", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\tif err := claim.validateObserved(preimage, field, initial.Operation()); err != nil {\n\t\treturn golem.Row[M]{}, publicScalarMutationError(descriptor.Metadata().ModelID(), err)\n\t}\n\tprogram, err := afterPrecheck(ctx, attempt)\n\tif err != nil {\n\t\treturn golem.Row[M]{}, publicScalarMutationError(descriptor.Metadata().ModelID(), err)\n\t}", After: "\tprogram, err := afterPrecheck(ctx, attempt)\n\tif err != nil {\n\t\treturn golem.Row[M]{}, publicScalarMutationError(descriptor.Metadata().ModelID(), err)\n\t}\n\tif err := claim.validateObserved(preimage, field, initial.Operation()); err != nil {\n\t\treturn golem.Row[M]{}, publicScalarMutationError(descriptor.Metadata().ModelID(), err)\n\t}"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_RESELECTS_AFTER_BEFORE_HOOK", "execute a second preimage SELECT instead of reusing the one locked snapshot", Patch{Path: "go/runtime/mutation_concurrency.go", Before: "\trow, err = executeVersionedScalarProjectionOnAttempt(ctx, app, attempt, descriptor, projection, program, preimage, hooks)", After: "\trecheckArguments, recheckErr := scalarMutationArguments(program.Operation(), 0, nextStatements[0], nil)\n\tif recheckErr != nil { return golem.Row[M]{}, publicScalarMutationError(descriptor.Metadata().ModelID(), recheckErr) }\n\tif _, recheckErr = queryExactlyOneMutationRow(ctx, attempt.queryer, app.registry, policyir.ModelID(descriptor.Metadata().ModelID()), app.provider, program.Operation(), 0, nextStatements[0], recheckArguments); recheckErr != nil { return golem.Row[M]{}, publicScalarMutationError(descriptor.Metadata().ModelID(), recheckErr) }\n\trow, err = executeVersionedScalarProjectionOnAttempt(ctx, app, attempt, descriptor, projection, program, preimage, hooks)"}, runtimeGate),
		{
			Label:   "CONCURRENCY_RUNTIME_REPREPARES_EXISTING_RETRY_VALUES",
			Summary: "recreate application-owned runtime values inside each existing-upsert attempt",
			Patches: []Patch{{Path: "go/runtime/mutation_concurrency.go", Before: "\treturn executeObservedVersionedUpsertRetries(ctx, caller.app, caller.executor, descriptor.Metadata().ModelID(), func(attemptContext context.Context, attempt uint32) (golem.Row[M], error) {\n\t\trow, executionErr := executeVersionedScalarKernel(attemptContext, caller.app, caller.executor, descriptor, projection, program, claim, hooks, afterPrecheck, attempt)", After: "\treturn executeObservedVersionedUpsertRetries(ctx, caller.app, caller.executor, descriptor.Metadata().ModelID(), func(attemptContext context.Context, attempt uint32) (golem.Row[M], error) {\n\t\tprogram, hooks, afterPrecheck, err = prepareCallerVersionedScalarExecution(caller, descriptor, mutationir.Update, &input, target, projection, newMutationRuntimeValues())\n\t\tif err != nil { return golem.Row[M]{}, err }\n\t\trow, executionErr := executeVersionedScalarKernel(attemptContext, caller.app, caller.executor, descriptor, projection, program, claim, hooks, afterPrecheck, attempt)"}},
			Gate:    runtimeGate, Timeout: 3 * time.Minute,
		},
		{
			Label:   "CONCURRENCY_RUNTIME_ACCEPTS_BEFORE_RETARGET",
			Summary: "accept a Before hook that changes the frozen target and locked precheck",
			Patches: []Patch{
				{Path: "go/runtime/mutation_concurrency.go", Before: "if transformedTarget == nil || !equalFrozenMutationTarget(target, *transformedTarget)", After: "if transformedTarget == nil && !equalFrozenMutationTarget(target, *transformedTarget)"},
				{Path: "go/runtime/mutation_concurrency.go", Before: "if !sameConcurrencyPrecheck(statements[0], nextStatements[0])", After: "if false && !sameConcurrencyPrecheck(statements[0], nextStatements[0])"},
			},
			Gate: runtimeGate, Timeout: 3 * time.Minute,
		},
		mutation("CONCURRENCY_RUNTIME_OMITS_HOOK_MUTABLE_GRANTS", "precompute grants only for fields authored before Before", Patch{Path: "go/internal/mutation/plan/build.go", Before: "\tif request.ConcurrencyPrecheck && operation == mutationir.Update {\n\t\tauthoredFields = mergeFields(authoredFields, concurrencyHookMutableFields(request))\n\t}", After: "\tif false && request.ConcurrencyPrecheck && operation == mutationir.Update {\n\t\tauthoredFields = mergeFields(authoredFields, concurrencyHookMutableFields(request))\n\t}"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_DROPS_PRIVATE_TOKEN_PREIMAGE", "omit the masked concurrency token from the private locked image", Patch{Path: "go/internal/mutation/sql/render.go", Before: "\treturn []policyir.FieldID{*context.concurrency}", After: "\treturn nil // mutant: private concurrency preimage omitted"}, runtimeGate),
		mutation("CONCURRENCY_RUNTIME_UNGROUPS_POSTCONDITION_OR", "allow an OR postcondition to escape the locked primary identity", Patch{Path: "go/internal/mutation/sql/render.go", Before: "\t\tparts = append(parts, \"(\"+fragment.text+\")\")\n\t\tbindings = append(bindings, fragment.bindings...)\n\t}\n\tpk := context.primaryKey()", After: "\t\tparts = append(parts, fragment.text)\n\t\tbindings = append(bindings, fragment.bindings...)\n\t}\n\tpk := context.primaryKey()"}, Gate{Directory: "go", Package: "./internal/mutation/sql", Test: "TestPostconditionDisjunctionRemainsGroupedUnderPrimaryIdentity"}),
	}
}
